data.divi_custom_css:
/* ============================================================================
   RMA OF MICHIGAN — DIVI 5 GLOBAL CSS · v2.0
   Cleaned + enhanced for Divi 5
   Paste into: Divi → Theme Options → General → Custom CSS
   (or enqueue via child theme functions.php)

   Design by Kevin Ryan · Innovation Network
   Last updated: June 2026

   ─────────────────────────────────────────────────────────────────────────
   WHAT'S NEW IN v2.0
   ─────────────────────────────────────────────────────────────────────────
   • @layer cascade — predictable specificity, fewer !important flags
   • color-mix() — derived palette colors (tints, borders) from base tokens
   • text-wrap: balance — headlines wrap evenly across lines
   • text-wrap: pretty — body text avoids orphans on last line
   • scroll-behavior + scroll-margin-top — anchor links land below header
   • accent-color — native form controls (checkbox, radio) match brand
   • field-sizing: content — textareas auto-size to content
   • Container queries — module-level responsiveness (independent of viewport)
   • forced-colors + prefers-reduced-transparency support (a11y)
   • content-visibility utility — skip offscreen layout/paint (perf)
   • Logical properties (margin-inline, padding-block) — future RTL ready
   • View Transitions API support — smooth page-to-page transitions
   ─────────────────────────────────────────────────────────────────────────

   TABLE OF CONTENTS
   §0   CASCADE LAYERS
   §1   DESIGN TOKENS
   §2   FONTS
   §3   RESET & BASE
   §4   TYPOGRAPHY · HEADINGS
   §5   TYPOGRAPHY · BODY & INLINE
   §6   SECTION LABEL UTILITY
   §7   SECTIONS & ROWS
   §8   BACKGROUND UTILITIES
   §9   BUTTONS · PRIMARY
   §10  BUTTON VARIANTS
   §11  BLURB MODULES
   §12  CTA / PROMO MODULES
   §13  ACCORDION & TOGGLE
   §14  TESTIMONIAL
   §15  TAB MODULE
   §16  CONTACT FORM
   §17  SLIDER / FULLWIDTH HEADER
   §18  PERSON MODULE (Physician Cards)
   §19  DIVIDERS & SEPARATORS
   §20  COUNTERS
   §21  IMAGE MODULE
   §22  SIDEBAR & WIDGETS
   §23  HEADER & NAVIGATION
   §24  MOBILE MENU
   §25  FOOTER
   §26  BLOG / POST CARDS
   §27  SCROLL ANIMATIONS
   §28  UTILITY CLASSES
   §29  RESPONSIVE
   §30  PRINT
   §31  ACCESSIBILITY
   §32  PERFORMANCE UTILITIES
   §33  VIEW TRANSITIONS
   ============================================================================ */


/* ─────────────────────────────────────────────────────────────
   §0  CASCADE LAYERS
   Order = priority (later layers win). Anything outside a layer
   beats everything inside, so Divi inline styles still need
   !important — but most rules below don't.
   ───────────────────────────────────────────────────────────── */
@layer reset, tokens, base, typography, components, divi, utilities, overrides;


/* ─────────────────────────────────────────────────────────────
   §1  DESIGN TOKENS  (CSS Custom Properties)
   Brand-source-of-truth. Change a base color and every derived
   tint/border updates automatically via color-mix().
   ───────────────────────────────────────────────────────────── */
@layer tokens {
  :root {
    /* ── Core Palette ── */
    --rma-blue:            #123883;
    --rma-navy:            #1a1a2e;
    --rma-white:           #ffffff;
    --rma-offwhite:        #f7f9fa;

    /* ── Extended Palette (derived where possible) ── */
    --rma-blue-hover:      #0e2d6b;  /* hand-tuned for AA contrast on white */
    --rma-blue-light:      #1a4499;
    --rma-blue-bright:     #2c6fce;
    --rma-blue-muted:      color-mix(in srgb, var(--rma-blue) 8%,  transparent);
    --rma-blue-tint:       color-mix(in srgb, var(--rma-blue) 4%,  transparent);
    --rma-border:          color-mix(in srgb, var(--rma-blue) 12%, transparent);
    --rma-border-light:    color-mix(in srgb, var(--rma-blue) 6%,  transparent);

    /* ── Text Colors ── */
    --rma-text-primary:    #1a1a2e;
    --rma-text-body:       #3a3a4a;
    --rma-text-secondary:  #5a5a6e;
    --rma-text-muted:      #8a8a9a;
    --rma-text-on-dark:    #ffffff;
    --rma-text-on-dark-75: color-mix(in srgb, #ffffff 75%, transparent);
    --rma-text-on-dark-60: color-mix(in srgb, #ffffff 60%, transparent);

    /* ── Typography ── */
    --rma-font-display:    'DM Serif Display', Georgia, 'Times New Roman', serif;
    --rma-font-body:       'DM Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;

    /* ── Spacing Scale ── */
    --rma-space-xs:        8px;
    --rma-space-sm:        16px;
    --rma-space-md:        24px;
    --rma-space-lg:        40px;
    --rma-space-xl:        64px;
    --rma-space-2xl:       96px;

    /* ── Radius ── */
    --rma-radius-sm:       6px;
    --rma-radius-md:       10px;
    --rma-radius-lg:       16px;
    --rma-radius-pill:     100px;

    /* ── Shadows ── */
    --rma-shadow-sm:       0 1px 3px  rgba(18, 56, 131, 0.06);
    --rma-shadow-md:       0 4px 16px rgba(18, 56, 131, 0.08);
    --rma-shadow-lg:       0 8px 32px rgba(18, 56, 131, 0.10);
    --rma-shadow-hover:    0 8px 24px rgba(18, 56, 131, 0.12);

    /* ── Motion ── */
    --rma-ease:            cubic-bezier(0.25, 0.46, 0.45, 0.94);
    --rma-duration:        0.3s;
    --rma-duration-slow:   0.5s;

    /* ── Scroll offset (header height) ─ used by scroll-margin-top */
    --rma-header-offset:   100px;

    /* ── Native form accent ── */
    accent-color: var(--rma-blue);
    color-scheme: light;
  }
}


/* ─────────────────────────────────────────────────────────────
   §2  FONTS
   Render-blocking @import. For best LCP, move this to
   <link rel="preconnect"> + <link rel="stylesheet"> in <head>
   via functions.php, then delete this block.
   ───────────────────────────────────────────────────────────── */
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,300;0,9..40,400;0,9..40,500;0,9..40,600;0,9..40,700;1,9..40,400;1,9..40,500&family=DM+Serif+Display&display=swap');


/* ─────────────────────────────────────────────────────────────
   §3  RESET & BASE
   ───────────────────────────────────────────────────────────── */
@layer reset {
  *, *::before, *::after {
    box-sizing: border-box;
  }

  html {
    scroll-behavior: smooth;
    -webkit-text-size-adjust: 100%;
            text-size-adjust: 100%;
  }

  /* Anchor targets land below the sticky header */
  :target,
  [id] {
    scroll-margin-block-start: var(--rma-header-offset);
  }

  img, picture, video, svg {
    max-width: 100%;
    height: auto;
    display: block;
  }

  ::selection {
    background: color-mix(in srgb, var(--rma-blue) 15%, transparent);
    color: var(--rma-navy);
  }
}

@layer base {
  body,
  #page-container {
    font-family: var(--rma-font-body);
    color: var(--rma-text-body);
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: optimizeLegibility;
    -webkit-tap-highlight-color: transparent;
  }

  body {
    background-color: var(--rma-white);
    line-height: 1.7;
    font-size: 16px;
    font-weight: 400;
  }
}


/* ─────────────────────────────────────────────────────────────
   §4  TYPOGRAPHY · HEADINGS
   ───────────────────────────────────────────────────────────── */
@layer typography {
  h1, h2, h3, h4, h5, h6,
  .et_pb_module_header,
  .et_pb_toggle_title,
  .et_pb_counter_title,
  .et_pb_slide_description .et_pb_slide_title {
    font-family: var(--rma-font-display);
    color: var(--rma-navy);
    font-weight: 400;
    line-height: 1.25;
    letter-spacing: -0.01em;
    text-wrap: balance;  /* even line lengths in modern browsers */
  }

  h1,
  .et_pb_slide_description .et_pb_slide_title {
    font-size: clamp(32px, 4.5vw, 52px);
    line-height: 1.15;
    margin-bottom: 20px;
  }
  h2 { font-size: clamp(26px, 3.5vw, 38px); margin-bottom: 16px; }
  h3 { font-size: clamp(22px, 2.5vw, 28px); margin-bottom: 14px; }
  h4 { font-size: clamp(18px, 2vw,   22px); margin-bottom: 12px; }

  h5 {
    font-family: var(--rma-font-body);
    font-size: 16px;
    font-weight: 600;
    letter-spacing: 0.03em;
    text-transform: uppercase;
    color: var(--rma-blue);
    margin-bottom: 10px;
  }

  h6 {
    font-family: var(--rma-font-body);
    font-size: 14px;
    font-weight: 600;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: var(--rma-text-secondary);
    margin-bottom: 8px;
  }
}


/* ─────────────────────────────────────────────────────────────
   §5  TYPOGRAPHY · BODY & INLINE
   ───────────────────────────────────────────────────────────── */
@layer typography {
  p,
  .et_pb_text_inner p,
  .et_pb_blurb_description p,
  .et_pb_toggle_content p,
  .et_pb_tab_content p,
  .et_pb_pricing_content li {
    font-family: var(--rma-font-body);
    font-size: 16px;
    line-height: 1.8;
    color: var(--rma-text-body);
    margin-bottom: 1em;
    text-wrap: pretty;  /* avoids single-word last lines (modern browsers) */
  }

  .et_pb_text_inner p:last-child,
  .et_pb_blurb_description p:last-child { margin-bottom: 0; }

  strong, b { font-weight: 600; color: var(--rma-navy); }
  em, i    { font-style: italic; }

  a {
    color: var(--rma-blue);
    text-decoration: none;
    transition: color var(--rma-duration) var(--rma-ease);
  }
  a:hover, a:focus { color: var(--rma-blue-hover); }

  ul li, ol li, .et_pb_text_inner li {
    font-family: var(--rma-font-body);
    font-size: 16px;
    line-height: 1.75;
    color: var(--rma-text-body);
    margin-bottom: 6px;
  }

  blockquote,
  .et_pb_testimonial_description p {
    font-family: var(--rma-font-display);
    font-size: 20px;
    line-height: 1.6;
    color: var(--rma-navy);
    border-inline-start: 3px solid var(--rma-blue);
    padding-inline-start: 24px;
    margin: 24px 0;
    font-style: normal;
  }
}


/* ─────────────────────────────────────────────────────────────
   §6  SECTION LABEL UTILITY
   Apply via Divi CSS class: rma-section-label  OR  rma-label
   ───────────────────────────────────────────────────────────── */
@layer components {
  .rma-section-label,
  .rma-label {
    display: inline-block;
    font-family: var(--rma-font-body);
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 2.5px;
    text-transform: uppercase;
    color: var(--rma-blue);
    margin-bottom: 8px;
  }
}


/* ─────────────────────────────────────────────────────────────
   §7  SECTIONS & ROWS · SPACING
   ───────────────────────────────────────────────────────────── */
@layer divi {
  .et_pb_section {
    padding: var(--rma-space-xl) 0;
    isolation: isolate; /* sections won't paint over a sticky header */
  }
  .et_pb_section.et_pb_section_first { padding-top: var(--rma-space-xl); }
  .et_pb_section.rma-section-tight   { padding: var(--rma-space-lg) 0; }

  .et_pb_row {
    max-width: 1140px !important;
    padding: 0 20px;
  }
  .et_pb_row.rma-row-wide   { max-width: 1280px !important; }
  .et_pb_row.rma-row-narrow { max-width: 780px  !important; }
}


/* ─────────────────────────────────────────────────────────────
   §8  BACKGROUND UTILITIES
   Apply via Divi Section/Row CSS class field
   ───────────────────────────────────────────────────────────── */
@layer utilities {
  .rma-bg-white    { background-color: var(--rma-white)    !important; }
  .rma-bg-offwhite { background-color: var(--rma-offwhite) !important; }
  .rma-bg-tint     { background-color: var(--rma-blue-tint) !important; }
  .rma-bg-navy     { background-color: var(--rma-navy)     !important; }

  .rma-bg-blue {
    background: linear-gradient(165deg,
      var(--rma-navy)       0%,
      var(--rma-blue)      55%,
      var(--rma-blue-light) 100%) !important;
  }

  /* Inverted text colors on dark backgrounds */
  :is(.rma-bg-blue, .rma-bg-navy) :is(h1, h2, h3, h4, .et_pb_module_header) {
    color: var(--rma-text-on-dark) !important;
  }
  :is(.rma-bg-blue, .rma-bg-navy) :is(p, li, .et_pb_blurb_description) {
    color: var(--rma-text-on-dark-75) !important;
  }
  :is(.rma-bg-blue, .rma-bg-navy) :is(.rma-section-label, .rma-label) {
    color: var(--rma-text-on-dark-60) !important;
  }
}


/* ─────────────────────────────────────────────────────────────
   §9  BUTTONS · PRIMARY
   Affects all Divi button modules
   ───────────────────────────────────────────────────────────── */
@layer divi {
  .et_pb_button,
  .et_pb_contact_submit,
  .et_pb_newsletter_button,
  .et_pb_promo_button,
  .et_pb_more_button,
  body .woocommerce .button,
  .et_pb_slide_description .et_pb_button {
    font-family: var(--rma-font-body) !important;
    font-size: 15px !important;
    font-weight: 500 !important;
    letter-spacing: 0.02em !important;
    text-transform: none !important;
    padding: 14px 32px !important;
    border-radius: var(--rma-radius-sm) !important;
    border: 2px solid var(--rma-blue) !important;
    background-color: var(--rma-blue) !important;
    color: var(--rma-white) !important;
    cursor: pointer;
    position: relative;
    overflow: hidden;
    transition:
      background-color var(--rma-duration) var(--rma-ease),
      border-color     var(--rma-duration) var(--rma-ease),
      transform        var(--rma-duration) var(--rma-ease),
      box-shadow       var(--rma-duration) var(--rma-ease) !important;
  }

  .et_pb_button:hover,
  .et_pb_contact_submit:hover,
  .et_pb_newsletter_button:hover,
  .et_pb_promo_button:hover,
  .et_pb_more_button:hover,
  body .woocommerce .button:hover {
    background-color: var(--rma-blue-hover) !important;
    border-color:     var(--rma-blue-hover) !important;
    color:            var(--rma-white)      !important;
    transform: translateY(-1px);
    box-shadow: var(--rma-shadow-hover);
  }

  .et_pb_button::after,
  .et_pb_more_button::after {
    font-size: 16px !important;
    margin-inline-start: 8px;
    transition: margin var(--rma-duration) var(--rma-ease);
  }
  .et_pb_button:hover::after,
  .et_pb_more_button:hover::after { margin-inline-start: 12px; }
}


/* ─────────────────────────────────────────────────────────────
   §10  BUTTON VARIANTS
   ───────────────────────────────────────────────────────────── */
@layer divi {
  /* Outline */
  .rma-btn-outline.et_pb_button,
  .rma-btn-outline .et_pb_button {
    background-color: transparent !important;
    color: var(--rma-blue) !important;
    border: 2px solid var(--rma-blue) !important;
  }
  .rma-btn-outline.et_pb_button:hover,
  .rma-btn-outline .et_pb_button:hover {
    background-color: var(--rma-blue) !important;
    color: var(--rma-white) !important;
  }

  /* Outline on dark backgrounds */
  :is(.rma-bg-blue, .rma-bg-navy) .rma-btn-outline.et_pb_button {
    border-color: color-mix(in srgb, #ffffff 40%, transparent) !important;
    color: var(--rma-white) !important;
    background-color: transparent !important;
  }
  :is(.rma-bg-blue, .rma-bg-navy) .rma-btn-outline.et_pb_button:hover {
    border-color: var(--rma-white) !important;
    background-color: color-mix(in srgb, #ffffff 10%, transparent) !important;
  }

  /* White (auto-applied to buttons on dark sections) */
  :is(.rma-bg-blue, .rma-bg-navy) .et_pb_button:not(.rma-btn-outline),
  .rma-btn-white.et_pb_button {
    background-color: var(--rma-white)     !important;
    border-color:     var(--rma-white)     !important;
    color:            var(--rma-blue)      !important;
  }
  :is(.rma-bg-blue, .rma-bg-navy) .et_pb_button:not(.rma-btn-outline):hover,
  .rma-btn-white.et_pb_button:hover {
    background-color: var(--rma-offwhite)  !important;
    border-color:     var(--rma-offwhite)  !important;
    color:            var(--rma-blue-hover) !important;
  }

  /* Small */
  .rma-btn-sm.et_pb_button,
  .rma-btn-sm .et_pb_button {
    padding: 10px 22px !important;
    font-size: 14px !important;
  }
}


/* ─────────────────────────────────────────────────────────────
   §11  BLURB MODULES
   ───────────────────────────────────────────────────────────── */
@layer divi {
  .et_pb_blurb {
    transition:
      transform  var(--rma-duration) var(--rma-ease),
      box-shadow var(--rma-duration) var(--rma-ease);
  }

  /* Card variant — apply CSS class: rma-blurb-card */
  .rma-blurb-card .et_pb_blurb_content {
    background: var(--rma-white);
    border: 1px solid var(--rma-border);
    border-radius: var(--rma-radius-lg);
    padding: 32px;
    contain: layout style;  /* paint isolation per card (perf) */
    transition:
      box-shadow   var(--rma-duration) var(--rma-ease),
      transform    var(--rma-duration) var(--rma-ease),
      border-color var(--rma-duration) var(--rma-ease);
  }
  .rma-blurb-card .et_pb_blurb_content:hover {
    box-shadow: var(--rma-shadow-lg);
    transform: translateY(-3px);
    border-color: color-mix(in srgb, var(--rma-blue) 18%, transparent);
  }
  .rma-blurb-card .et_pb_main_blurb_image { margin-bottom: 20px; }

  .et_pb_blurb h4,
  .et_pb_blurb .et_pb_module_header {
    font-family: var(--rma-font-display);
    font-size: 20px;
    color: var(--rma-navy);
    margin-bottom: 10px;
  }
  .et_pb_blurb_description {
    font-size: 15px;
    color: var(--rma-text-body);
    line-height: 1.75;
  }
  .et_pb_blurb .et-pb-icon { color: var(--rma-blue) !important; }

  /* Icon-box variant — apply CSS class: rma-icon-box */
  .rma-icon-box .et_pb_main_blurb_image {
    background: var(--rma-blue-muted);
    width: 56px; height: 56px;
    border-radius: var(--rma-radius-md);
    display: flex; align-items: center; justify-content: center;
    margin-bottom: 20px;
  }
  .rma-icon-box .et-pb-icon { font-size: 26px !important; }
}


/* ─────────────────────────────────────────────────────────────
   §12  CTA / PROMO MODULES
   ───────────────────────────────────────────────────────────── */
@layer divi {
  .et_pb_promo {
    background: linear-gradient(165deg, var(--rma-navy) 0%, var(--rma-blue) 100%) !important;
    border-radius: var(--rma-radius-lg);
    padding: 56px 48px !important;
    border: none !important;
  }
  .et_pb_promo .et_pb_promo_description :is(h2, .et_pb_module_header) {
    font-family: var(--rma-font-display) !important;
    color: var(--rma-text-on-dark) !important;
    font-size: clamp(24px, 3vw, 32px);
  }
  .et_pb_promo .et_pb_promo_description p {
    color: var(--rma-text-on-dark-75) !important;
    font-size: 16px;
  }
}


/* ─────────────────────────────────────────────────────────────
   §13  ACCORDION & TOGGLE
   ───────────────────────────────────────────────────────────── */
@layer divi {
  .et_pb_toggle {
    border: 1px solid var(--rma-border) !important;
    border-radius: var(--rma-radius-md) !important;
    margin-bottom: 12px;
    overflow: hidden;
    contain: layout style;
    transition: border-color var(--rma-duration) var(--rma-ease);
  }
  .et_pb_toggle:hover { border-color: color-mix(in srgb, var(--rma-blue) 20%, transparent); }

  .et_pb_toggle_title {
    font-family: var(--rma-font-display) !important;
    font-size: 18px !important;
    color: var(--rma-navy) !important;
    padding: 20px 24px !important;
    font-weight: 400 !important;
  }
  .et_pb_toggle_open .et_pb_toggle_title { color: var(--rma-blue) !important; }

  .et_pb_toggle_content {
    padding: 0 24px 20px !important;
    font-size: 15px;
    line-height: 1.75;
    color: var(--rma-text-body);
  }
  .et_pb_toggle .et_pb_toggle_title::before {
    color: var(--rma-blue) !important;
    font-size: 18px;
  }
}


/* ─────────────────────────────────────────────────────────────
   §14  TESTIMONIAL
   ───────────────────────────────────────────────────────────── */
@layer divi {
  .et_pb_testimonial {
    background: var(--rma-offwhite) !important;
    border: 1px solid var(--rma-border) !important;
    border-radius: var(--rma-radius-lg) !important;
    padding: 36px !important;
  }
  .et_pb_testimonial_description p {
    font-family: var(--rma-font-display) !important;
    font-size: 18px !important;
    color: var(--rma-navy) !important;
    line-height: 1.65;
    border-inline-start: none;
    padding-inline-start: 0;
  }
  .et_pb_testimonial_author {
    font-family: var(--rma-font-body) !important;
    color: var(--rma-blue) !important;
    font-weight: 600;
    font-size: 14px !important;
  }
  .et_pb_testimonial_meta {
    font-size: 13px;
    color: var(--rma-text-secondary);
  }
  .et_pb_testimonial_portrait {
    border: 3px solid var(--rma-blue-muted) !important;
  }
}


/* ─────────────────────────────────────────────────────────────
   §15  TAB MODULE
   ───────────────────────────────────────────────────────────── */
@layer divi {
  .et_pb_tabs .et_pb_tab_active a {
    color: var(--rma-blue) !important;
    border-bottom-color: var(--rma-blue) !important;
  }
  .et_pb_tabs .et_pb_tabs_controls li a {
    font-family: var(--rma-font-body) !important;
    font-weight: 500;
    font-size: 15px;
    color: var(--rma-text-secondary);
    transition: color var(--rma-duration) var(--rma-ease);
  }
  .et_pb_tabs .et_pb_tabs_controls li a:hover { color: var(--rma-blue); }
  .et_pb_tab_content {
    font-family: var(--rma-font-body) !important;
    font-size: 15px;
    line-height: 1.8;
    padding: 28px 0;
  }
}


/* ─────────────────────────────────────────────────────────────
   §16  CONTACT FORM
   Modern enhancements: accent-color (native checkboxes/radios),
   field-sizing (auto-growing textarea).
   ───────────────────────────────────────────────────────────── */
@layer divi {
  .et_pb_contact_form_container .et_pb_contact_form :is(
    input[type="text"],
    input[type="email"],
    input[type="tel"],
    input[type="number"],
    input[type="date"],
    textarea, select) {
    font-family: var(--rma-font-body) !important;
    font-size: 15px;
    color: var(--rma-text-primary);
    background: var(--rma-offwhite);
    border: 1.5px solid var(--rma-border) !important;
    border-radius: var(--rma-radius-sm) !important;
    padding: 14px 18px !important;
    accent-color: var(--rma-blue);
    transition:
      border-color var(--rma-duration) var(--rma-ease),
      box-shadow   var(--rma-duration) var(--rma-ease);
  }

  .et_pb_contact_form_container .et_pb_contact_form textarea {
    field-sizing: content;  /* auto-grows with content where supported */
    min-block-size: 100px;
  }

  .et_pb_contact_form_container .et_pb_contact_form :is(input, textarea, select):focus {
    border-color: var(--rma-blue) !important;
    box-shadow: 0 0 0 3px color-mix(in srgb, var(--rma-blue) 10%, transparent);
    outline: none;
    background: var(--rma-white);
  }

  .et_pb_contact_form_container .et_pb_contact_form label {
    font-family: var(--rma-font-body) !important;
    font-size: 13px;
    font-weight: 600;
    letter-spacing: 0.03em;
    color: var(--rma-text-secondary);
    margin-bottom: 6px;
  }

  .et_pb_contact_form_container .et_pb_contact_form :is(input, textarea)::placeholder {
    color: var(--rma-text-muted);
  }
}


/* ─────────────────────────────────────────────────────────────
   §17  SLIDER / FULLWIDTH HEADER
   ───────────────────────────────────────────────────────────── */
@layer divi {
  .et_pb_slider,
  .et_pb_fullwidth_header {
    font-family: var(--rma-font-body) !important;
  }

  .et_pb_slider .et_pb_slide_description h2,
  .et_pb_fullwidth_header .et_pb_fullwidth_header_container h1 {
    font-family: var(--rma-font-display) !important;
    color: var(--rma-text-on-dark);
    line-height: 1.15;
  }

  .et_pb_slider .et_pb_slide_description .et_pb_slide_content,
  .et_pb_fullwidth_header .et_pb_header_content_wrapper p {
    font-size: 17px;
    line-height: 1.7;
    color: var(--rma-text-on-dark-75);
  }

  .et_pb_slider .et-pb-controllers a {
    background: color-mix(in srgb, #ffffff 30%, transparent) !important;
  }
  .et_pb_slider .et-pb-controllers a.et-pb-active-control {
    background: var(--rma-white) !important;
  }
}


/* ─────────────────────────────────────────────────────────────
   §18  PERSON MODULE  (Physician / Team Cards)
   ───────────────────────────────────────────────────────────── */
@layer divi {
  .et_pb_team_member { text-align: center; }

  .et_pb_team_member h4,
  .et_pb_team_member .et_pb_module_header {
    font-family: var(--rma-font-display) !important;
    font-size: 22px;
    color: var(--rma-navy);
    margin-bottom: 4px;
  }
  .et_pb_team_member .et_pb_member_position {
    font-family: var(--rma-font-body) !important;
    font-size: 14px;
    color: var(--rma-blue);
    font-weight: 500;
    margin-bottom: 12px;
  }
  .et_pb_team_member .et_pb_team_member_image {
    border-radius: var(--rma-radius-lg);
    overflow: hidden;
    margin-bottom: 20px;
    aspect-ratio: 4 / 5;
  }
  .et_pb_team_member .et_pb_team_member_image img {
    width: 100%; height: 100%;
    object-fit: cover; object-position: center top;
  }
  .et_pb_team_member .et_pb_team_member_description p {
    font-size: 15px; line-height: 1.7;
  }
}


/* ─────────────────────────────────────────────────────────────
   §19  DIVIDERS & SEPARATORS
   ───────────────────────────────────────────────────────────── */
@layer divi {
  .et_pb_divider .et_pb_divider_internal {
    border-top-color: var(--rma-border) !important;
  }
  hr {
    border: none;
    border-top: 1px solid var(--rma-border);
    margin: var(--rma-space-lg) 0;
  }
}


/* ─────────────────────────────────────────────────────────────
   §20  COUNTERS
   ───────────────────────────────────────────────────────────── */
@layer divi {
  .et_pb_number_counter .percent p {
    font-family: var(--rma-font-display) !important;
    color: var(--rma-blue) !important;
  }
  .et_pb_counter_title {
    font-family: var(--rma-font-body) !important;
    font-weight: 500;
    color: var(--rma-navy);
    font-size: 14px;
  }
  .et_pb_counter_amount {
    background-color: var(--rma-blue) !important;
    border-radius: var(--rma-radius-pill);
  }
  .et_pb_counter_container .et_pb_counter_container_inner {
    background: var(--rma-blue-muted);
    border-radius: var(--rma-radius-pill);
  }
}


/* ─────────────────────────────────────────────────────────────
   §21  IMAGE MODULE
   ───────────────────────────────────────────────────────────── */
@layer divi {
  .rma-img-rounded .et_pb_image_wrap {
    border-radius: var(--rma-radius-lg);
    overflow: hidden;
  }
  .rma-img-shadow .et_pb_image_wrap {
    box-shadow: var(--rma-shadow-md);
  }
  .rma-img-circle .et_pb_image_wrap {
    border-radius: 50%;
    overflow: hidden;
    border: 4px solid var(--rma-blue-muted);
  }
}


/* ─────────────────────────────────────────────────────────────
   §22  SIDEBAR & WIDGETS
   ───────────────────────────────────────────────────────────── */
@layer divi {
  .et_pb_widget_area h4.widgettitle {
    font-family: var(--rma-font-body) !important;
    font-size: 13px;
    font-weight: 600;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: var(--rma-blue);
    padding-bottom: 12px;
    border-bottom: 2px solid var(--rma-border);
    margin-bottom: 16px;
  }
  .et_pb_widget_area ul li a {
    font-family: var(--rma-font-body) !important;
    font-size: 15px;
    color: var(--rma-text-body);
    padding: 8px 0;
    display: block;
    border-bottom: 1px solid var(--rma-border-light);
    transition:
      color           var(--rma-duration) var(--rma-ease),
      padding-inline-start var(--rma-duration) var(--rma-ease);
  }
  .et_pb_widget_area ul li a:hover {
    color: var(--rma-blue);
    padding-inline-start: 6px;
  }
}


/* ─────────────────────────────────────────────────────────────
   §23  HEADER & NAVIGATION
   Critical: `isolation: isolate` + high z-index keeps the
   header above any hero-section stacking context.
   ───────────────────────────────────────────────────────────── */
@layer divi {
  #main-header,
  #top-header {
    font-family: var(--rma-font-body) !important;
  }

  #main-header {
    box-shadow: 0 1px 0 var(--rma-border-light);
    isolation: isolate;
    z-index: 99999;
  }

  /* Primary nav links */
  #top-menu li a,
  .et_mobile_menu li a {
    font-family: var(--rma-font-body) !important;
    font-size: 14px !important;
    font-weight: 500;
    letter-spacing: 0.02em;
    color: var(--rma-navy) !important;
    transition: color var(--rma-duration) var(--rma-ease);
  }
  #top-menu li a:hover,
  #top-menu li.current-menu-item > a { color: var(--rma-blue) !important; }

  /* Dropdown menus */
  #top-menu li ul.sub-menu {
    background: var(--rma-white) !important;
    border: 1px solid var(--rma-border);
    border-radius: var(--rma-radius-sm);
    box-shadow: var(--rma-shadow-md);
    padding: 8px 0;
  }
  #top-menu li ul.sub-menu li a {
    font-size: 13px !important;
    padding: 8px 20px !important;
    color: var(--rma-text-body) !important;
  }
  #top-menu li ul.sub-menu li a:hover {
    color: var(--rma-blue) !important;
    background: var(--rma-blue-tint);
  }

  .et-fixed-header #main-header { box-shadow: var(--rma-shadow-sm) !important; }

  /* Utility bar (top header) */
  #top-header {
    background-color: var(--rma-navy) !important;
    font-size: 13px;
    padding: 6px 0;
  }
  #top-header a,
  #top-header .et-social-icon a { color: var(--rma-text-on-dark-75) !important; }
  #top-header a:hover { color: var(--rma-white) !important; }
}


/* ─────────────────────────────────────────────────────────────
   §24  MOBILE MENU
   ───────────────────────────────────────────────────────────── */
@layer divi {
  .et_mobile_menu {
    background: var(--rma-white) !important;
    border: 1px solid var(--rma-border) !important;
    border-radius: 0 0 var(--rma-radius-md) var(--rma-radius-md);
    box-shadow: var(--rma-shadow-lg);
    padding: 12px 0;
  }
  .et_mobile_menu li a {
    padding: 12px 24px !important;
    border-bottom: 1px solid var(--rma-border-light);
  }
  .et_mobile_menu li a:hover {
    background: var(--rma-blue-tint);
    color: var(--rma-blue) !important;
  }
  .mobile_menu_bar::before { color: var(--rma-navy) !important; }
}


/* ─────────────────────────────────────────────────────────────
   §25  FOOTER
   ───────────────────────────────────────────────────────────── */
@layer divi {
  #main-footer {
    background-color: var(--rma-navy) !important;
    font-family: var(--rma-font-body) !important;
  }

  #footer-widgets .footer-widget h4.widgettitle,
  #footer-widgets .footer-widget h4 {
    font-family: var(--rma-font-body) !important;
    font-size: 12px !important;
    font-weight: 600;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: var(--rma-text-on-dark-60) !important;
    margin-bottom: 20px;
    padding-bottom: 12px;
    border-bottom: 1px solid color-mix(in srgb, #ffffff 8%, transparent);
  }

  #footer-widgets .footer-widget li a,
  #footer-widgets a {
    font-family: var(--rma-font-body) !important;
    font-size: 14px;
    color: var(--rma-text-on-dark-75) !important;
    line-height: 2;
    transition:
      color                var(--rma-duration) var(--rma-ease),
      padding-inline-start var(--rma-duration) var(--rma-ease);
  }
  #footer-widgets .footer-widget li a:hover,
  #footer-widgets a:hover {
    color: var(--rma-white) !important;
    padding-inline-start: 4px;
  }

  #footer-widgets p,
  #footer-widgets .footer-widget p {
    font-size: 14px;
    color: var(--rma-text-on-dark-75);
    line-height: 1.7;
  }

  #footer-bottom {
    background-color: color-mix(in srgb, #000000 15%, transparent) !important;
    font-size: 13px;
    padding: 16px 0;
  }
  #footer-bottom :is(#footer-info, a) {
    color: var(--rma-text-on-dark-60) !important;
    font-family: var(--rma-font-body) !important;
    font-size: 13px;
  }
  #footer-bottom a:hover { color: var(--rma-white) !important; }

  #footer-widgets .et-social-icon a,
  #main-footer  .et-social-icon a {
    color: var(--rma-text-on-dark-60) !important;
    transition: color var(--rma-duration) var(--rma-ease);
  }
  #footer-widgets .et-social-icon a:hover,
  #main-footer  .et-social-icon a:hover { color: var(--rma-white) !important; }
}


/* ─────────────────────────────────────────────────────────────
   §26  BLOG / POST CARDS
   ───────────────────────────────────────────────────────────── */
@layer divi {
  .et_pb_blog_grid .et_pb_post {
    border: 1px solid var(--rma-border);
    border-radius: var(--rma-radius-lg);
    overflow: hidden;
    contain: layout style;
    transition:
      box-shadow var(--rma-duration) var(--rma-ease),
      transform  var(--rma-duration) var(--rma-ease);
  }
  .et_pb_blog_grid .et_pb_post:hover {
    box-shadow: var(--rma-shadow-lg);
    transform: translateY(-3px);
  }
  .et_pb_blog_grid .et_pb_post .entry-title a,
  .et_pb_post h2 a {
    font-family: var(--rma-font-display) !important;
    color: var(--rma-navy);
    font-size: 20px;
    transition: color var(--rma-duration) var(--rma-ease);
  }
  .et_pb_blog_grid .et_pb_post .entry-title a:hover,
  .et_pb_post h2 a:hover { color: var(--rma-blue); }

  .et_pb_post .post-meta,
  .et_pb_post .post-meta a {
    font-family: var(--rma-font-body) !important;
    font-size: 13px;
    color: var(--rma-text-muted);
  }
  .et_pb_post .post-content p { font-size: 15px; line-height: 1.7; }
}


/* ─────────────────────────────────────────────────────────────
   §27  SCROLL ANIMATIONS  (CSS-only)
   Apply CSS class: rma-fade-up
   ───────────────────────────────────────────────────────────── */
@layer utilities {
  .rma-fade-up {
    opacity: 0;
    transform: translateY(24px);
    transition:
      opacity   0.6s var(--rma-ease),
      transform 0.6s var(--rma-ease);
  }
  .rma-fade-up.et_pb_animation_triggered,
  .rma-fade-up.rma-visible {
    opacity: 1;
    transform: translateY(0);
  }

  /* Stagger children — apply to parent row: rma-stagger */
  .rma-stagger .et_pb_column:nth-child(1) .et_pb_module { transition-delay: 0s;   }
  .rma-stagger .et_pb_column:nth-child(2) .et_pb_module { transition-delay: 0.1s; }
  .rma-stagger .et_pb_column:nth-child(3) .et_pb_module { transition-delay: 0.2s; }
  .rma-stagger .et_pb_column:nth-child(4) .et_pb_module { transition-delay: 0.3s; }
}


/* ─────────────────────────────────────────────────────────────
   §28  UTILITY CLASSES
   ───────────────────────────────────────────────────────────── */
@layer utilities {
  /* Text alignment */
  .rma-text-center { text-align: center !important; }
  .rma-text-left   { text-align: left   !important; }
  .rma-text-right  { text-align: right  !important; }

  /* Show / hide by viewport */
  @media (max-width: 980px)  { .rma-hide-mobile  { display: none !important; } }
  @media (min-width: 981px)  { .rma-hide-desktop { display: none !important; } }

  /* Max-width content limiters */
  .rma-max-720 :is(.et_pb_text_inner, .et_pb_blurb_description) { max-width: 720px; }
  .rma-max-560 :is(.et_pb_text_inner, .et_pb_blurb_description) { max-width: 560px; }

  /* Accent border-left */
  .rma-border-left {
    border-inline-start: 3px solid var(--rma-blue);
    padding-inline-start: 24px;
  }

  /* Card surface */
  .rma-card {
    background: var(--rma-white);
    border: 1px solid var(--rma-border);
    border-radius: var(--rma-radius-lg);
    padding: 32px;
    contain: layout style;
    transition: box-shadow var(--rma-duration) var(--rma-ease);
  }
  .rma-card:hover { box-shadow: var(--rma-shadow-md); }

  /* Highlight box */
  .rma-highlight {
    background: var(--rma-blue-muted);
    border-inline-start: 3px solid var(--rma-blue);
    border-radius: 0 var(--rma-radius-md) var(--rma-radius-md) 0;
    padding: 24px 28px;
  }

  /* Stat callout */
  .rma-stat .et_pb_text_inner {
    display: flex;
    align-items: center;
    gap: 14px;
    background: var(--rma-blue-muted);
    border: 1px solid var(--rma-border);
    border-radius: var(--rma-radius-md);
    padding: 16px 24px;
  }

  /* Aspect ratio helpers */
  .rma-aspect-1-1   { aspect-ratio: 1 / 1; }
  .rma-aspect-4-3   { aspect-ratio: 4 / 3; }
  .rma-aspect-4-5   { aspect-ratio: 4 / 5; }
  .rma-aspect-16-9  { aspect-ratio: 16 / 9; }
}


/* ─────────────────────────────────────────────────────────────
   §29  RESPONSIVE
   ───────────────────────────────────────────────────────────── */
@layer divi {
  /* Tablet */
  @media (max-width: 980px) {
    .et_pb_section { padding: var(--rma-space-lg) 0; }
    h1, .et_pb_slide_description .et_pb_slide_title { font-size: 32px; }
    h2 { font-size: 26px; }
    h3 { font-size: 22px; }
    .et_pb_promo { padding: 40px 32px !important; }
    .et_pb_button { padding: 12px 28px !important; }
  }

  /* Mobile */
  @media (max-width: 767px) {
    body { font-size: 15px; }
    .et_pb_section { padding: 40px 0; }
    h1, .et_pb_slide_description .et_pb_slide_title { font-size: 28px; }
    h2 { font-size: 24px; }
    h3 { font-size: 20px; }
    .et_pb_row { padding: 0 16px; }
    .et_pb_promo {
      padding: 32px 24px !important;
      border-radius: var(--rma-radius-md);
    }
    .et_pb_toggle_title { font-size: 16px !important; padding: 16px 20px !important; }
    .et_pb_contact_form_container .et_pb_contact_form :is(
      input[type="text"], input[type="email"], textarea) { padding: 12px 14px !important; }
    .et_pb_column { margin-bottom: 20px; }
  }
}


/* ─────────────────────────────────────────────────────────────
   §30  PRINT
   ───────────────────────────────────────────────────────────── */
@media print {
  #main-header,
  #top-header,
  #main-footer,
  .et_pb_button,
  .et-social-icons { display: none !important; }

  body,
  .et_pb_text_inner p {
    font-size: 12pt;
    color: #000;
    line-height: 1.5;
  }
  h1, h2, h3, h4 {
    color: #000;
    page-break-after: avoid;
  }
  a { color: #000; text-decoration: underline; }
  .et_pb_section { padding: 12pt 0; }
}


/* ─────────────────────────────────────────────────────────────
   §31  ACCESSIBILITY
   ───────────────────────────────────────────────────────────── */
@layer base {
  /* Visible focus rings */
  :is(a, button, .et_pb_button, input, textarea, select, summary):focus-visible {
    outline: 2px solid var(--rma-blue);
    outline-offset: 2px;
    border-radius: 4px;
  }

  /* Skip link */
  .screen-reader-text:focus {
    background: var(--rma-white);
    color: var(--rma-navy);
    padding: 12px 24px;
    font-size: 14px;
    font-weight: 600;
    z-index: 100000;
    position: fixed;
    inset-block-start: 0;
    inset-inline-start: 0;
    box-shadow: var(--rma-shadow-md);
  }

  /* Reduced-motion preference — kills animations + hover transforms */
  @media (prefers-reduced-motion: reduce) {
    *, *::before, *::after {
      animation-duration: 0.01ms !important;
      animation-iteration-count: 1 !important;
      transition-duration: 0.01ms !important;
      scroll-behavior: auto !important;
    }
  }

  /* Reduced-transparency preference — drop blur/transparent effects */
  @media (prefers-reduced-transparency: reduce) {
    :is(.et_pb_promo, .et_pb_blurb, .rma-card, .rma-highlight) {
      backdrop-filter: none !important;
    }
  }

  /* Windows High Contrast Mode (forced colors) */
  @media (forced-colors: active) {
    .et_pb_button {
      border: 2px solid CanvasText !important;
      background: ButtonFace !important;
      color: ButtonText !important;
      forced-color-adjust: none;
    }
    .et_pb_toggle,
    .rma-card,
    .et_pb_blurb_content { border: 1px solid CanvasText; }
  }
}


/* ─────────────────────────────────────────────────────────────
   §32  PERFORMANCE UTILITIES
   Apply via Divi CSS class
   ───────────────────────────────────────────────────────────── */
@layer utilities {
  /* Skip layout/paint for offscreen sections — big INP win */
  .rma-cv {
    content-visibility: auto;
    contain-intrinsic-size: 1px 720px;
  }

  /* Paint isolation per card (already on many components above) */
  .rma-contain {
    contain: layout style;
  }

  /* Hint heavy hover transforms to the GPU */
  .rma-will-animate {
    will-change: transform;
  }
}


/* ─────────────────────────────────────────────────────────────
   §33  VIEW TRANSITIONS  (progressive enhancement)
   Pages opt in by adding a transition-name to elements they
   want to morph between routes.
   ───────────────────────────────────────────────────────────── */
@layer base {
  @view-transition { navigation: auto; }

  ::view-transition-old(root),
  ::view-transition-new(root) {
    animation-duration: var(--rma-duration);
    animation-timing-function: var(--rma-ease);
  }
}


